SELECT id, payment_id, idempotency_key, cancel_amount, cancel_reason, status, transaction_key, failure_code, failure_message, requested_at, canceled_at, created_at FROM payment_cancellations WHERE payment_id IN
#{paymentId}
ORDER BY id DESC

SELECT     AS label,
       COALESCE(SUM(t.signed_amount), 0)     AS net_sales_amount
  FROM (
        SELECT approved_at AS occurred_at, amount AS signed_amount
          FROM payments
         WHERE approved_at >= #{from}
           AND approved_at < #{to}
         UNION ALL
        SELECT canceled_at AS occurred_at, -cancel_amount AS signed_amount
          FROM payment_cancellations
         WHERE status = 'DONE'
           AND canceled_at >= #{from}
           AND canceled_at < #{to}
       ) t
 GROUP BY 
 ORDER BY MIN(t.occurred_at)
